        .wb_clk_i    (clk_i),
        .wb_rst_i    (~rst_ni),     // Caravel reset is active-high
        .wbs_stb_i   (1'b0),
        .wbs_cyc_i   (1'b0),
        .wbs_we_i    (1'b0),
        .wbs_sel_i   (4'b0),
        .wbs_dat_i   (32'b0),
        .wbs_adr_i   (32'b0),
        .wbs_ack_o   (wbs_ack_o),
        .wbs_dat_o   (wbs_dat_o),
        .la_data_in  (128'b0),
        .la_data_out (la_data_out),
        .la_oenb     (128'b0),
        .io_in       (38'b0),
        .io_out      (io_out),
        .io_oeb      (io_oeb),
        .analog_io   (),            // inout, leave unconnected
