`endif

    // ── Surface the Ibex instruction-fetch PC for cocotb ───────────────
    assign dbg_pc_o = dut.u_ibex.instr_addr;

    // ── Boot ROM load ──────────────────────────────────────────────────
    // The rv_core_ibex_tlul declares BootRomFile = "" by default and its
    // time-0 initial fills boot_rom with NOPs. Override here
    // from an always-block on the first posedge so we run after all
    // time-0 inits and before reset deasserts.
    reg boot_rom_loaded = 1'b0;
    always @(posedge clk_i) begin
        if (!boot_rom_loaded) begin
            $readmemh("../../../boot_rom.hex", dut.u_ibex.boot_rom);
            $display("[tb_smoke] loaded boot_rom.hex; boot_rom[0]=%08h", dut.u_ibex.boot_rom[0]);
